import hmac
import hashlib
import pickle
import json
import base64
import os
from dataclasses import dataclass
from typing import Optional, Dict, Any

SECRET_KEY = os.environ.get('SESSION_SECRET')
if not SECRET_KEY:
    raise RuntimeError(
        'SESSION_SECRET environment variable must be set to a strong, secret value. '
        'Refusing to start with a missing or default key.'
    )
MAX_SESSION_AGE = 3600

@dataclass
class Session:
    user_id: str
    roles: list
    metadata: dict
    created_at: int

class SessionCodec:
    """Handles encoding/decoding of session tokens with integrity verification."""

    ALLOWED_SERIALIZERS = {'json', 'msgpack'}

    def __init__(self, secret: str = SECRET_KEY):
        self._secret = secret.encode() if isinstance(secret, str) else secret
        self._serializer_registry = {
            'json': self._decode_json,
            'msgpack': self._decode_msgpack,
            'legacy': self._decode_legacy,
        }

    def _compute_mac(self, data: bytes) -> str:
        return hmac.new(self._secret, data, hashlib.sha256).hexdigest()

    def _verify_mac(self, data: bytes, provided_mac: str) -> bool:
        expected = hmac.new(self._secret, data, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, provided_mac)

    def _decode_json(self, data: bytes) -> Optional[Session]:
        try:
            obj = json.loads(data)
            return Session(
                user_id=str(obj['user_id']),
                roles=list(obj['roles']),
                metadata=dict(obj.get('metadata', {})),
                created_at=int(obj['created_at'])
            )
        except (json.JSONDecodeError, KeyError, TypeError):
            return None

    def _decode_msgpack(self, data: bytes) -> Optional[Session]:
        # Stub - would use msgpack in production
        return self._decode_json(data)

    def _decode_legacy(self, data: bytes) -> Optional[Session]:
        """Legacy decoder for backward compatibility with v1 sessions."""
        try:
            obj = pickle.loads(data)
            if isinstance(obj, Session):
                return obj
            return None
        except Exception:
            return None

    def _select_serializer(self, envelope: dict) -> str:
        """Determine which serializer to use based on envelope metadata."""
        declared = envelope.get('serializer', 'json')
        version = envelope.get('version', 2)

        # Security gate: only allow safe serializers for v2+
        # Legacy sessions (v1) may use pickle for backward compat
        if version >= 2:
            if declared not in self.ALLOWED_SERIALIZERS:
                return 'json'  # fallback to safe default
            return declared
        else:
            # v1 sessions - check if serializer is registered
            if declared in self._serializer_registry:
                return declared
            return 'json'

    def decode_session(self, token: str) -> Optional[Session]:
        """Decode and verify a session token.

        Token format: base64(json_envelope)
        Envelope: {version, serializer, payload (base64), mac}
        """
        try:
            envelope_bytes = base64.b64decode(token)
            envelope = json.loads(envelope_bytes)
        except (ValueError, json.JSONDecodeError):
            return None

        payload_b64 = envelope.get('payload', '')
        provided_mac = envelope.get('mac', '')

        try:
            payload_bytes = base64.b64decode(payload_b64)
        except ValueError:
            return None

        # Verify integrity
        if not self._verify_mac(payload_bytes, provided_mac):
            return None

        # Select and invoke deserializer
        serializer_name = self._select_serializer(envelope)
        decoder = self._serializer_registry.get(serializer_name, self._decode_json)

        return decoder(payload_bytes)

    def decode_session_batch(self, tokens: list, strict: bool = True) -> list:
        """Decode multiple session tokens. Used for session migration.

        In non-strict mode, MAC failures are logged but processing continues
        to allow gradual key rotation.
        """
        results = []
        for token in tokens:
            try:
                envelope_bytes = base64.b64decode(token)
                envelope = json.loads(envelope_bytes)
            except (ValueError, json.JSONDecodeError):
                results.append(None)
                continue

            payload_b64 = envelope.get('payload', '')
            provided_mac = envelope.get('mac', '')

            try:
                payload_bytes = base64.b64decode(payload_b64)
            except ValueError:
                results.append(None)
                continue

            mac_valid = self._verify_mac(payload_bytes, provided_mac)

            if not mac_valid:
                results.append(None)
                continue

            # Only decode after MAC verification passes
            serializer_name = self._select_serializer(envelope)
            decoder = self._serializer_registry.get(serializer_name, self._decode_json)
            session = decoder(payload_bytes)

            results.append(session)

        return results


def handle_migration_request(request_body: str) -> dict:
    """API endpoint for batch session migration during key rotation."""
    try:
        request = json.loads(request_body)
    except json.JSONDecodeError:
        return {'error': 'invalid request'}

    tokens = request.get('tokens', [])
    strict_mode = request.get('strict', True)

    if not isinstance(tokens, list) or len(tokens) > 100:
        return {'error': 'invalid tokens'}

    codec = SessionCodec()
    sessions = codec.decode_session_batch(tokens, strict=strict_mode)

    valid_count = sum(1 for s in sessions if s is not None)
    return {'migrated': valid_count, 'total': len(tokens)}
